use rusqlite::{params, Connection};
use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use tokio::sync::broadcast;
use tracing::{info, warn};

use crate::chunks::id::ChunkId;
use crate::chunks::store::ChunkStore;
use crate::error::ContentError;
use crate::events::ContentEvent;
use crate::hashing::{hash_bytes, hash_stream};
use crate::identity::ContentId;
use crate::manifest::store::ManifestStore;
use crate::metadata::ContentStorageState;

/// Detailed report generated by an integrity audit of a content object.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct ContentAuditReport {
    pub content_id: ContentId,
    pub manifest_found: bool,
    pub total_chunks: u32,
    pub verified_chunks: u32,
    pub missing_chunks: Vec<ChunkId>,
    pub corrupted_chunks: Vec<ChunkId>,
    pub physical_file_intact: bool,
    pub is_healthy: bool,
}

/// Service that audits local content, manifests, and chunks for integrity, bitrot, or missing data.
pub struct IntegrityAuditor {
    conn: Arc<Mutex<Connection>>,
    chunk_store: Arc<ChunkStore>,
    manifest_store: Arc<ManifestStore>,
    objects_dir: PathBuf,
    event_tx: broadcast::Sender<ContentEvent>,
}

impl IntegrityAuditor {
    pub fn new(
        conn: Arc<Mutex<Connection>>,
        chunk_store: Arc<ChunkStore>,
        manifest_store: Arc<ManifestStore>,
        objects_dir: PathBuf,
        event_tx: broadcast::Sender<ContentEvent>,
    ) -> Self {
        Self {
            conn,
            chunk_store,
            manifest_store,
            objects_dir,
            event_tx,
        }
    }

    /// Performs a comprehensive integrity audit on a single content object.
    pub async fn audit_content(
        &self,
        content_id: &ContentId,
    ) -> Result<ContentAuditReport, ContentError> {
        let _ = self.event_tx.send(ContentEvent::IntegrityAuditStarted {
            content_id: Some(*content_id),
            scope: "single".to_string(),
        });

        // 1. Retrieve manifest
        let manifest = match self.manifest_store.get_by_content_id(content_id) {
            Ok(m) => m,
            Err(_) => {
                warn!(content_id = %content_id, "Audit failed: Manifest missing");
                let _ = self.event_tx.send(ContentEvent::IntegrityAuditFailed {
                    content_id: *content_id,
                    chunk_id: None,
                    reason: "Manifest not found in local store".to_string(),
                });
                return Ok(ContentAuditReport {
                    content_id: *content_id,
                    manifest_found: false,
                    total_chunks: 0,
                    verified_chunks: 0,
                    missing_chunks: Vec::new(),
                    corrupted_chunks: Vec::new(),
                    physical_file_intact: false,
                    is_healthy: false,
                });
            }
        };

        let mut verified_chunks = 0;
        let mut missing_chunks = Vec::new();
        let mut corrupted_chunks = Vec::new();

        // 2. Audit all chunks in manifest
        for desc in &manifest.chunks {
            let cid = desc.chunk_id;
            match self.chunk_store.get(&cid).await {
                Ok(data) => {
                    let actual_hash = hash_bytes(&data);
                    let actual_id = ChunkId::from_bytes(actual_hash.to_bytes());
                    if actual_id == cid {
                        verified_chunks += 1;
                    } else {
                        warn!(
                            chunk_id = %cid,
                            actual = %actual_id,
                            "Chunk corruption detected during audit"
                        );
                        if !corrupted_chunks.contains(&cid) {
                            corrupted_chunks.push(cid);
                        }
                        let _ = self.event_tx.send(ContentEvent::CorruptionDetected {
                            content_id: *content_id,
                            chunk_id: Some(cid),
                            reason: format!(
                                "Chunk hash mismatch: expected {}, got {}",
                                cid, actual_id
                            ),
                        });
                    }
                }
                Err(_) => {
                    if !missing_chunks.contains(&cid) {
                        missing_chunks.push(cid);
                    }
                }
            }
        }

        // 3. Check physical file
        let rel_path = content_id.relative_storage_path();
        let obj_path = self.objects_dir.join(rel_path);
        let mut physical_file_intact = false;

        if obj_path.exists() {
            if let Ok(mut file) = tokio::fs::File::open(&obj_path).await {
                if let Ok(computed_cid) = hash_stream(&mut file).await {
                    physical_file_intact = &computed_cid == content_id;
                }
            }
        }

        let is_healthy = missing_chunks.is_empty()
            && corrupted_chunks.is_empty()
            && verified_chunks == manifest.chunk_count
            && physical_file_intact;

        if !is_healthy {
            warn!(
                content_id = %content_id,
                missing = missing_chunks.len(),
                corrupted = corrupted_chunks.len(),
                file_ok = physical_file_intact,
                "Content audit detected integrity failures"
            );

            // Mark corrupted in DB fail-closed
            let conn = self
                .conn
                .lock()
                .map_err(|e| ContentError::LockError(e.to_string()))?;
            let _ = conn.execute(
                "UPDATE content_index SET storage_state = ?2 WHERE content_id = ?1",
                params![content_id.to_hex(), ContentStorageState::Corrupted.as_str()],
            );

            let _ = self.event_tx.send(ContentEvent::IntegrityAuditFailed {
                content_id: *content_id,
                chunk_id: corrupted_chunks.first().copied(),
                reason: "Content has missing or corrupted constituent chunks".to_string(),
            });
        } else {
            info!(content_id = %content_id, "Content audit passed successfully");
        }

        Ok(ContentAuditReport {
            content_id: *content_id,
            manifest_found: true,
            total_chunks: manifest.chunk_count,
            verified_chunks,
            missing_chunks,
            corrupted_chunks,
            physical_file_intact,
            is_healthy,
        })
    }

    /// Audits all content objects registered in the content index.
    pub async fn audit_all(&self) -> Result<Vec<ContentAuditReport>, ContentError> {
        let _ = self.event_tx.send(ContentEvent::IntegrityAuditStarted {
            content_id: None,
            scope: "all".to_string(),
        });

        let content_ids: Vec<ContentId> = {
            let conn = self
                .conn
                .lock()
                .map_err(|e| ContentError::LockError(e.to_string()))?;
            let mut stmt = conn.prepare("SELECT content_id FROM content_index")?;
            let rows = stmt.query_map([], |row| {
                let hex_str: String = row.get(0)?;
                Ok(hex_str)
            })?;

            let mut ids = Vec::new();
            for hex_str in rows.flatten() {
                if let Ok(cid) = ContentId::from_hex(&hex_str) {
                    ids.push(cid);
                }
            }
            ids
        };

        let mut reports = Vec::with_capacity(content_ids.len());
        for cid in &content_ids {
            reports.push(self.audit_content(cid).await?);
        }

        Ok(reports)
    }
}
